        example: '<span class="mark-blue">Пример SOAP-запроса к банку:</span><br><code>&lt;soap:Envelope&gt;<br>&nbsp;&nbsp;&lt;soap:Body&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;PayOrder&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;orderId&gt;123&lt;/orderId&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;amount&gt;1000&lt;/amount&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;/PayOrder&gt;<br>&nbsp;&nbsp;&lt;/soap:Body&gt;<br>&lt;/soap:Envelope&gt;</code><br><br><span class="mark-blue">Ответ банка:</span><br><code>&lt;soap:Envelope&gt;<br>&nbsp;&nbsp;&lt;soap:Body&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;PayOrderResponse&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;status&gt;success&lt;/status&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;transactionId&gt;456&lt;/transactionId&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;/PayOrderResponse&gt;<br>&nbsp;&nbsp;&lt;/soap:Body&gt;<br>&lt;/soap:Envelope&gt;</code><br><br>SOAP <span class="mark-blue">строго определяет</span> структуру сообщения, поэтому банк всегда понимает запрос и отвечает в понятном формате.',
