        simple: 'Проверка полных бизнес-сценариев от начала до конца, включая взаимодействие со всеми внешними системами.',
        example: 'Вы проверяете полный путь: пользователь заходит на сайт → выбирает пиццу → оформляет заказ → оплачивает через платёжную систему → получает уведомление на почту → пицца доставляется. Все системы (сайт, платёжный шлюз, почтовый сервис, система доставки) работают вместе.',
