        simple: 'Система, преобразующая доменные имена в IP-адреса.',
        example: '<span class="mark-green">Как ответить на собеседовании:</span><br><br><span class="mark-green">Вступление:</span> «DNS — это телефонная книга интернета. Она переводит понятные человеку домены (например, google.com) в IP-адреса, понятные компьютерам.»<br><br><span class="mark-green">Как работает:</span><br>Вводите google.com → DNS-сервер находит IP-адрес (например, 142.250.74.78) → направляет вас к серверу Google.<br><br><span class="mark-green">Что проверяет тестировщик:</span><ul><li>Правильность настройки DNS для разных окружений (dev, test, prod).</li><li>Время ответа DNS (может влиять на скорость загрузки).</li><li>Наличие записей (A, CNAME, MX) для поддоменов.</li></ul>',
        academic: 'Что такое DNS-сервер и как он работает?',
